# Sort numbers stored on different machines
...
Given **n ** machines in the form of the Linked list.
Each machine contains some numbers in sorted form.
But the amount of numbers, each machine has is not fixed.
Output the numbers from all the machine in sorted non-decreasing form.
...
> **Explanation: ** Sorted Number from all Machine is [1, 5, 10, 30, 35, 45, 90, 130]
### [Approach 1] - Using a Priority Queue - Good for Varying-Sized Arrays or Lists
> The `mergeLists` function merges sorted linked lists using a min heap, repeatedly extracting the smallest element and inserting the next node.
The `externalSort` function converts the linked lists into a vector, calls `mergeLists` to get the final sorted list, and prints it.
Changing the comparison in `CompareNode` allows sorting in descending order.
C++
`
```
#include <bits/stdc++.h>
using namespace std;
struct ListNode {
int data;
ListNode* next;
ListNode(int val) : data(val), next(nullptr) {}
};
struct CompareNode {
bool operator()(const ListNode* a, const ListNode* b) {
return a->data > b->data;
}
};
void push(ListNode*& head, int data) {
ListNode* newNode = new ListNode(data);
newNode->next = head;
head = newNode;
}
void PrintList(ListNode* head) {
while (head) {
cout << head->data;
if (head->next) cout << " ";
head = head->next;
}
cout << endl;
}
ListNode* mergelist(vector<ListNode*>& list) {
priority_queue<ListNode*, vector<ListNode*>, CompareNode> minHeap;
for (auto li : list)
if (li) minHeap.push(li);
ListNode dummy(0), *tail = &dummy;
while (!minHeap.empty()) {
ListNode* node = minHeap.top();
minHeap.pop();
tail->next = node;
tail = tail->next;
if (node->next) minHeap.push(node->next);
}
return dummy.next;
}
ListNode* externalSort(vector<ListNode*>& list) {
ListNode* sortedList = mergelist(list);
return sortedList;
}
int main() {
int N = 3;
vector<ListNode*> list(N, nullptr);
push(list[0], 50);
push(list[0], 40);
push(list[0], 30);
push(list[1], 45);

